/// A single node in the [`StoreSubscriptions`] tree. Each path is a specific view into the store
/// and can be subscribed to and marked dirty separately.
///
/// Each node tracks two different kinds of subscribers:
/// - `shallow_subscribers` only care about changes to *this exact* path. Reading the length of a
///   `Vec` or the set of keys in a map is a shallow read; it should not re-run when a nested value
///   deep inside the structure changes.
/// - `deep_subscribers` care about changes to this path *or any of its descendants*. Reading a full
///   value out of the store is a deep read; it should re-run whenever anything nested underneath it
///   changes.
///
/// When a path is marked dirty, every subscriber in the subtree underneath it is notified, and the
/// deep subscribers of every ancestor are notified as well so that parent-level reads observe writes
/// to their children.
#[derive(Clone, Default)]
pub(crate) struct SelectorNode {
    /// Subscribers that only care about writes to this exact path.
    shallow_subscribers: HashSet<ReactiveContext>,
    /// Subscribers that care about writes to this path or any descendant path.
    deep_subscribers: HashSet<ReactiveContext>,
    /// The child nodes of this node, keyed by path segment.
    children: HashMap<PathKey, SelectorNode>,
}

impl SelectorNode {
    /// Get an existing selector node by its path.
    fn get(&self, path: &[PathKey]) -> Option<&SelectorNode> {
        let [first, rest @ ..] = path else {
            return Some(self);
        };
        self.children.get(first).and_then(|child| child.get(rest))
    }

    /// Get an existing selector node by its path mutably.
    fn get_mut(&mut self, path: &[PathKey]) -> Option<&mut SelectorNode> {
        let [first, rest @ ..] = path else {
            return Some(self);
        };
        self.children
            .get_mut(first)
            .and_then(|child| child.get_mut(rest))
    }

    /// Get a selector mutably or create one if it doesn't exist. This is used when subscribing to
    /// a path that may not exist yet.
    fn get_mut_or_default(&mut self, path: &[PathKey]) -> &mut SelectorNode {
        let [first, rest @ ..] = path else {
            return self;
        };
        self.children
            .entry(*first)
            .or_default()
            .get_mut_or_default(rest)
    }

    /// Get the path to each node under this node
    ///
    /// This is used to mark nodes dirty recursively when a Store is written to.
    fn paths_under(&self, current_path: &[PathKey], paths: &mut Vec<Box<[PathKey]>>) {
        paths.push(current_path.into());
        for (i, child) in self.children.iter() {
            let mut child_path: Vec<PathKey> = current_path.into();
            child_path.push(*i);
            child.paths_under(&child_path, paths);
        }
    }

    /// Get paths to only children at or after a certain index.
    ///
    /// This is used when inserting a new item into a list.
    /// Items at and after the index that is inserted need to be marked dirty because the value that index points to may have changed.
    fn paths_at_and_after_index(
        &self,
        path: &[PathKey],
        index: usize,
        paths: &mut Vec<Box<[PathKey]>>,
    ) {
        let Some(node) = self.get(path) else {
            return;
        };

        // Mark the nodes at and after the index as dirty
        for (i, child) in node.children.iter() {
            if *i as usize >= index {
                let mut child_path: Vec<PathKey> = path.into();
                child_path.push(*i);
                child.paths_under(&child_path, paths);
            }
        }
    }

    /// Remove a path from the subscription tree
    fn remove(&mut self, path: &[PathKey]) {
        let [first, rest @ ..] = path else {
            return;
        };
        if let Some(node) = self.children.get_mut(first) {
            if rest.is_empty() {
                self.children.remove(first);
            } else {
                node.remove(rest);
            }
        }
    }

    /// Returns true if this node has no subscribers and no children, so it can be garbage collected.
    fn is_empty(&self) -> bool {
        self.shallow_subscribers.is_empty()
            && self.deep_subscribers.is_empty()
            && self.children.is_empty()
    }
}

